import numpy as np
import matplotlib.pyplot as plt
from scipy import stats
import sys


def find_intersection(sorted_Y_desc, t1, slope2, intercept2):
    indices1 = np.arange(0, t1)
    Y1 = sorted_Y_desc[:t1]
    slope1, intercept1, _, _, _ = stats.linregress(indices1, Y1)
    intersection_x = (intercept2 - intercept1) / (slope1 - slope2)
    intersection_y = slope1 * intersection_x + intercept1
    closest_intersection_index = round(intersection_x)

    return slope1, intercept1, intersection_x, intersection_y, closest_intersection_index


def regr_for_tail(Y, t2):
    indices2 = np.arange(t2, len(Y))
    Y2 = Y[t2:]
    slope2, intercept2, _, _, _ = stats.linregress(indices2, Y2)
    return slope2, intercept2


def calculate_error(sorted_Y_desc, slope1, intercept1, closest_intersection_index):
    indices1 = np.arange(0, min(len(sorted_Y_desc), closest_intersection_index))
    Y = sorted_Y_desc[:closest_intersection_index]

    error = np.sum((Y - (slope1 * indices1 + intercept1)) ** 2)
    return error


def optimize_approximation(sorted_Y_desc, start_ind_head, slope2, intercept2):
    min_error = float('inf')
    best_t1 = 0
    best_slope1 = 0
    best_intercept1 = 0
    best_intersection_x = 0
    best_intersection_y = 0
    best_closest_intersection_index = 0

    q_start = start_ind_head
    if q_start >= len(sorted_Y_desc) // 2:
        q_start = 3

    for t1 in range(q_start, len(sorted_Y_desc) // 2):
        slope1, intercept1, intersection_x, intersection_y, closest_intersection_index = find_intersection(
            sorted_Y_desc, t1, slope2, intercept2)
        if (closest_intersection_index > 2):
            error = calculate_error(
                sorted_Y_desc, slope1, intercept1, closest_intersection_index)
            if error < min_error:
                min_error = error
                best_t1 = t1
                best_slope1 = slope1
                best_intercept1 = intercept1
                best_intersection_x = intersection_x
                best_intersection_y = intersection_y
                best_closest_intersection_index = closest_intersection_index

    return best_t1, best_slope1, best_intercept1, best_intersection_x, best_intersection_y, best_closest_intersection_index


def distance_to_line(x, y, mb, b):
    return abs(mb * x - y + b) / np.sqrt(mb**2 + 1)


def perpendicular_point(x0, y0, m, b):
    # Если прямая вертикальна
    if m == 0:
        return x0, b
    # x координата точки пересечения
    x = (m * x0 + y0 - b) / (m + 1 / m)
    # y координата точки пересечения
    y = m * x + b
    return x, y


# Find the inflection point from sorted_Y_desc (index in sorted_Y_desc) as the closest point to the bisector line.
# The bisector line formed by two intersecting lines (slope1, intercept1) and (slope2, intercept2).
def inflection_point(sorted_Y_desc, slope1, intercept1, slope2, intercept2):

    # Calculate the slope of the bisector
    # slope_b1 = (slope1 + slope2 + np.sqrt(1 + slope1**2) *
    #            np.sqrt(1 + slope2**2)) / (1 - slope1 * slope2)
    slope_b2 = (slope1 + slope2 - np.sqrt(1 + slope1**2) * np.sqrt(1 + slope2**2)) / (1 - slope1 * slope2)

    # Find the intersection point of two lines (slope1, intercept1) and (slope2, intercept2)
    x0 = (intercept2 - intercept1) / (slope1 - slope2)
    y0 = slope1 * x0 + intercept1

    # defind parameter b in the bisector line equation
    # mb = slope_b1 # internal bisector
    mb = slope_b2
    b = y0 - mb * x0

    # Equation of the bisector
    # y_values = mb * x_values + b

    # Search for closest point in sorted_Y_desc to the bisector line
    min_distance = float('inf')
    best_inflection_index = 0

    for i in range(len(sorted_Y_desc) // 2):
        x = i
        y = sorted_Y_desc[i]
        distance = distance_to_line(x, y, mb, b)
        # print("distance=",distance)
        # print("x=",x)
        # print("y=",y)
        # print("mb * x + b=",mb * x + b)
        # print(f"Перпендикулярная точка: ({px}, {py})")
        if distance < min_distance:
            min_distance = distance
            px, py = perpendicular_point(x, y, mb, b)
            best_inflection_index = round(px)
    return best_inflection_index


def inflection_point_in_sorted_Y(sorted_Y_desc):
    N = len(sorted_Y_desc)
    # start interval of head part of sorted_Y_desc for regression [0,start_ind_head]
    start_ind_head = 3
    ind_tail = N // 2  # interval [ind_tail, N-1]

    # regression for the tail of sorted_Y_desc
    slope2, intercept2 = regr_for_tail(sorted_Y_desc, ind_tail)
    best_ind_head, slope1, intercept1, intersection_x, intersection_y, closest_intersection_index = optimize_approximation(
        sorted_Y_desc, start_ind_head, slope2, intercept2)
    inflection_index = inflection_point(
        sorted_Y_desc, slope1, intercept1, slope2, intercept2)

    #################################
    # inflection_index is the boundary for determining the optimal size of the top in the sorted_Y_desc
    #################################
    return inflection_index


def inflection_point_in_sorted_Y_with_plot(sorted_Y_desc, filename):
    N = len(sorted_Y_desc)
    start_ind_head = 3
    ind_tail = N // 2

    slope2, intercept2 = regr_for_tail(sorted_Y_desc, ind_tail)
    best_ind_head, slope1, intercept1, intersection_x, intersection_y, closest_intersection_index = optimize_approximation(
        sorted_Y_desc, start_ind_head, slope2, intercept2)
    inflection_index = inflection_point(
        sorted_Y_desc, slope1, intercept1, slope2, intercept2)

    plt.figure(figsize=(12, 6))
    indices = np.arange(len(sorted_Y_desc))
    plt.plot(indices, sorted_Y_desc, label='Data', color='blue')

    n1 = closest_intersection_index + 20
    indices1 = np.arange(0, n1)
    plt.plot(indices1, slope1 * indices1 + intercept1,
             label='Regression Line 1', color='red')

    indices2 = np.arange(0, N)
    plt.plot(indices2, slope2 * indices2 + intercept2,
             label='Regression Line 2', color='green')

    plt.scatter(inflection_index, sorted_Y_desc[inflection_index], color='orange',
                zorder=5, label=f'Inflection point (i={inflection_index})')

    plt.xlabel('Index (i)')
    plt.ylabel('Y[i]')
    plt.title('Inflection point in the sorted Y')
    plt.legend()
    plt.grid(True)

    # Сохранение графика
    if filename == "":
        plt.show()
    else:
        plt.savefig(filename)
        plt.clf()


